const abortError=()=>Object.assign(new Error('stale-or-disposed'),{name:'AbortError'});
export function createBrowserTransport(baseURL){return{async load(t,signal){const r=await fetch(new URL(t.file,baseURL),{signal});if(!r.ok)throw Error(`packet-http-${r.status}`);const reader=r.body.getReader(),parts=[];let n=0;try{for(;;){const{value,done}=await reader.read();if(done)break;n+=value.length;if(n>t.encodedBytes)throw Error('encoded-size-cap');parts.push(value);}}catch(e){await reader.cancel();throw e;}finally{reader.releaseLock();}const out=new Uint8Array(n);let p=0;for(const b of parts){out.set(b,p);p+=b.length;}return out;},async inflate(bytes,limit,signal){const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate')).getReader(),out=new Uint8Array(limit);let n=0;try{for(;;){if(signal.aborted)throw abortError();const{value,done}=await reader.read();if(done)break;if(n+value.length>limit)throw Error('decoded-size-cap');out.set(value,n);n+=value.length;}if(n!==limit)throw Error('decoded-size-short');return out;}catch(e){await reader.cancel();throw e;}finally{reader.releaseLock();}}};}
